let V12_MODEL_CACHE = null;
function crsV12Model() { return V12_MODEL_CACHE || (V12_MODEL_CACHE = JSON.parse(V12_MODEL_TEXT)); }

// Raw model output for one row of inputs (array in crsV12Model().features order; null = missing), plus how much each input pushed it.
function crsV12Raw(x) {
  const M = crsV12Model(), push = new Array(x.length).fill(0);
  let f = M.f0;
  for (const t of M.trees) {
    let node = 0;
    for (let d = 0; d < M.depth; d++) {
      const sp = t.s[d][node];
      const go = sp ? ((x[sp[0]] === null || x[sp[0]] === undefined || Number.isNaN(x[sp[0]])) ? 1 : (sp[1] !== null && x[sp[0]] >= sp[1] ? 1 : 0)) : 0;
      const next = node * 2 + go;
      if (sp) push[sp[0]] += M.lr * (t.v[d + 1][next] - t.v[d][node]);
      node = next;
    }
    f += M.lr * t.v[M.depth][node];
  }
  return { f, push };
}

// Cut-offs are set per rating group, so a strong player is compared with other strong players.
function crsV12Score(f, rating) {
  const bands = crsV12Model().anchorsByRating;
  const set = bands.find(b => (rating || 0) >= b.lo && (rating || 0) < b.hi) || bands[0];
  const A = set.anchors;
  if (f <= A[0][0]) return A[0][1];
  for (let i = 1; i < A.length; i++) if (f <= A[i][0]) return A[i - 1][1] + (A[i][1] - A[i - 1][1]) * (f - A[i - 1][0]) / (A[i][0] - A[i - 1][0]);
  return 100;
}

// Score one Chess.com account. calc = a RiskCalculator (its accuracy tables are what traits() compares against).
// Returns null when there are no rated games in the format to judge.
function crsV12Assess(calc, username, profile, stats, games, fmt) {
  if (!games || !games.length) return null;
  const { t } = crsV12TraitsFor(calc)(String(username || ''), profile || {}, stats || {}, games, fmt);
  if (!t.recentGames || t.fmt === 'daily') return null;          // daily games keep the v11 score
  const x = crsV12Model().features.map(k => k.startsWith('fmt_') ? (t.fmt === k.slice(4) ? 1 : 0) : (typeof t[k] === 'number' && Number.isFinite(t[k]) ? t[k] : null));
  const { f, push } = crsV12Raw(x);
  const fam = {};
  push.forEach((p, i) => { const k = V12_FAMILY_OF[i]; if (k) fam[k] = (fam[k] || 0) + p; });
  const reasons = Object.entries(fam).filter(([, v]) => v >= 0.15).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([k, v]) => ({ key: k, label: V12_FAMILY[k].label, icon: V12_FAMILY[k].icon, push: Math.round(v * 100) / 100 }));
  const families = Object.entries(fam).map(([k, v]) => ({ key: k, label: V12_FAMILY[k].label, push: Math.round(v * 100) / 100 })).sort((a, b) => b.push - a.push);
  return { score: crsV12Score(f, t.ratingNow), raw: f, reasons, families, ageDays: t.ageDays, games: t.recentGames };
}
